// Local HTTP endpoint that Claude Code *hooks* report to — the authoritative agent-status
// source (replaces last-terminal-line guessing). Every Claude session CmdrZone launches gets
// `--settings <userData>/claude-hooks.json` (generated by buildHooksSettings) plus a
// CMDRZONE_SESSION_ID env var carrying its terminal-tab id. The hook command is a curl
// one-liner that POSTs the hook's stdin JSON to /hook/<token>/<terminalId> here.
//
// Durability: port + token are persisted by the caller, so sessions that outlive an app
// restart (tmux) keep reporting to the next instance. No electron imports (main-safe core).

import http from 'node:http'

/** Fields we pick out of a Claude Code hook's stdin JSON. */
export interface HookEventData {
  event: string
  toolName?: string
  message?: string
  claudeSessionId?: string
  transcriptPath?: string
  cwd?: string
  source?: string
}

export interface HookServer {
  port: number
  close(): void
}

const MAX_BODY = 256 * 1024

function parseBody(raw: string): HookEventData | null {
  try {
    const j = JSON.parse(raw) as Record<string, unknown>
    const s = (v: unknown): string | undefined => (typeof v === 'string' && v ? v : undefined)
    const event = s(j.hook_event_name)
    if (!event) return null
    return {
      event,
      toolName: s(j.tool_name),
      message: s(j.message),
      claudeSessionId: s(j.session_id),
      transcriptPath: s(j.transcript_path),
      cwd: s(j.cwd),
      source: s(j.source)
    }
  } catch {
    return null
  }
}

/**
 * Start the hook endpoint on 127.0.0.1. Tries `preferredPort` first (so sessions from a
 * previous run keep working); falls back to an OS-assigned port if it's taken.
 */
export function createHookServer(opts: {
  preferredPort: number
  token: string
  onEvent: (terminalId: string, ev: HookEventData) => void
}): Promise<HookServer> {
  const server = http.createServer((req, res) => {
    // POST /hook/<token>/<terminalId>
    const m = /^\/hook\/([^/]+)\/([^/?]+)/.exec(req.url ?? '')
    if (req.method !== 'POST' || !m || m[1] !== opts.token) {
      res.statusCode = 403
      res.end()
      return
    }
    const terminalId = decodeURIComponent(m[2]!)
    let body = ''
    req.on('data', (chunk: Buffer) => {
      body += chunk.toString('utf8')
      if (body.length > MAX_BODY) req.destroy()
    })
    req.on('end', () => {
      const ev = parseBody(body)
      if (ev) opts.onEvent(terminalId, ev)
      res.statusCode = 204
      res.end()
    })
    req.on('error', () => {
      /* client went away — nothing to do */
    })
  })

  return new Promise((resolve, reject) => {
    let triedFallback = false
    const listen = (port: number): void => {
      server.listen(port, '127.0.0.1')
    }
    server.on('error', (err: NodeJS.ErrnoException) => {
      if (!triedFallback && err.code === 'EADDRINUSE') {
        triedFallback = true
        listen(0)
        return
      }
      reject(err)
    })
    server.on('listening', () => {
      const addr = server.address()
      const port = typeof addr === 'object' && addr ? addr.port : 0
      server.unref()
      resolve({ port, close: () => server.close() })
    })
    listen(opts.preferredPort > 0 ? opts.preferredPort : 0)
  })
}

/**
 * The settings JSON passed to `claude --settings` at launch. One identical fire-and-forget
 * command on every lifecycle event — the server reads `hook_event_name` from the body, so a
 * single endpoint serves them all. Guarded on CMDRZONE_SESSION_ID (no-op if a user runs claude
 * against this file manually) and always `exit 0` so a dead/unreachable app never blocks the
 * agent. Both `PermissionRequest` (current Claude Code) and `Notification` (older versions)
 * are registered — unknown event names are ignored, so the pair covers every install.
 */
export function buildHooksSettings(port: number, token: string): string {
  const cmd =
    `[ -n "$CMDRZONE_SESSION_ID" ] && curl -s -o /dev/null -m 3 -X POST ` +
    `-H 'Content-Type: application/json' --data-binary @- ` +
    `"http://127.0.0.1:${port}/hook/${token}/$CMDRZONE_SESSION_ID"; exit 0`
  const entry = [{ hooks: [{ type: 'command', command: cmd, timeout: 10 }] }]
  const events = [
    'SessionStart',
    'UserPromptSubmit',
    'PreToolUse',
    'PermissionRequest',
    'Notification',
    'Stop',
    'SessionEnd'
  ]
  return JSON.stringify({ hooks: Object.fromEntries(events.map((e) => [e, entry])) }, null, 2)
}
